class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        long long low = 0, high = 0;
        for (int n : nums) {
            if (n > low) low = n;
            high += n;
        }
        auto canSplit = [&](long long maxSum) {
            int pieces = 1;
            long long currSum = 0;
            for (int n : nums) {
                if (currSum + n > maxSum) {
                    pieces++;
                    currSum = n;
                } else {
                    currSum += n;
                }
            }
            return pieces <= k;
        };
        while (low < high) {
            long long mid = low + (high - low) / 2;
            if (canSplit(mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return (int)low;
    }
};

class Solution {
    public int splitArray(int[] nums, int k) {
        long low = 0, high = 0;
        for (int n : nums) {
            if (n > low) low = n;
            high += n;
        }
        while (low < high) {
            long mid = low + (high - low) / 2;
            int pieces = 1;
            long currSum = 0;
            for (int n : nums) {
                if (currSum + n > mid) {
                    pieces++;
                    currSum = n;
                } else {
                    currSum += n;
                }
            }
            if (pieces <= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return (int)low;
    }
}

var splitArray = function(nums, k) {
    let low = Math.max(...nums);
    let high = nums.reduce((a, b) => a + b, 0);

    const canSplit = (maxSum) => {
        let pieces = 1;
        let currSum = 0;
        for (const n of nums) {
            if (currSum + n > maxSum) {
                pieces++;
                currSum = n;
            } else {
                currSum += n;
            }
        }
        return pieces <= k;
    };

    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (canSplit(mid)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
};
